const context = $('Assemble Enrichment Context').first().json;
const llmResponse = $input.first().json;

const brief = llmResponse?.choices?.[0]?.message?.content ?? '(brief generation failed -- route to manual triage)';

return [{
  json: {
    alert: context.alert,
    enrichment_summary: context.enrichment,
    triage_brief: brief,
    disposition: null,
    disposed_by: null,
    status: 'awaiting_analyst_review'
  }
}];
